CREATE TABLE "cambios_salariales" ("id" TEXT NOT NULL PRIMARY KEY,"empleadoId" TEXT NOT NULL,"sueldoAnterior" DECIMAL NOT NULL,"sueldoNuevo" DECIMAL NOT NULL,"vigenteDesde" DATETIME NOT NULL,"motivo" TEXT NOT NULL,"estado" TEXT NOT NULL DEFAULT 'PENDIENTE',"usuarioId" TEXT NOT NULL,"usuarioNombre" TEXT NOT NULL,"resueltoEn" DATETIME,"resueltoPorId" TEXT,"resueltoPorNombre" TEXT,"motivoRechazo" TEXT,"creadoEn" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "cambios_salariales_empleadoId_fkey" FOREIGN KEY ("empleadoId") REFERENCES "empleados"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "cambios_salariales_empleadoId_vigenteDesde_idx" ON "cambios_salariales"("empleadoId","vigenteDesde");
